/bin/bash -c "python3 - <<'PY'
from pathlib import Path
import re, statistics, importlib.util
for n in [19,20]:
    print('\\nTABLE', 11 if n==19 else 13)
    groups={'G-Eval':[], 'CheckEval':[]}
    for line in Path(f'tmp/pdfs/page-{n}.txt').read_text().splitlines():
        if line.startswith('Table '):break
        vals=re.findall(r'-?\\d+\\.\\d+',line)
        if len(vals)<10:continue
        vals=list(map(float, vals[-10:]))
        means=[statistics.mean(vals[:8:2]),statistics.mean(vals[1:8:2])]
        label=line[:line.find(re.findall(r'-?\\d+\\.\\d+',line)[-10])].strip()
        if any(abs(a-b)>0.00011 for a,b in zip(means,vals[8:])):
            print('Average mismatch:',label,'computed',means,'printed',vals[8:])
        for name in groups:
            if name in line:groups[name].append(vals[8:])
    for name,rows in groups.items():
        print(name, 'n=',len(rows),'mean=',[round(statistics.mean(x),6) for x in zip(*rows)],'variance=',[round(statistics.variance(x),6) for x in zip(*rows)])
print('scipy available:',bool(importlib.util.find_spec('scipy')))
PY"
